mapper.select:
SELECT id, article_id, page_id, message_id, send_name, send_email, receive_name, receive_email, content, create_time FROM blog_email
AND (content LIKE CONCAT('%', #{keyword}, '%') OR send_name LIKE CONCAT('%', #{keyword}, '%') OR receive_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{limit}
